(()=>{document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("contact-form");e&&e.addEventListener("submit",async s=>{s.preventDefault();const c=document.getElementById("contact-name").value,r=document.getElementById("contact-email").value,l=document.getElementById("contact-subject").value,d=document.getElementById("contact-message").value,t=e.querySelector('button[type="submit"]'),i=t.textContent;t.textContent="Odes\xEDl\xE1m...",t.disabled=!0;try{const n=window.getCSRFToken?await window.getCSRFToken():null,a=await fetch("/api/contact",{method:"POST",headers:{"Content-Type":"application/json",...n&&{"X-CSRF-Token":n}},body:JSON.stringify({name:c,email:r,subject:l,message:d})}),o=await a.json().catch(()=>({}));if(!a.ok||o.success!==!0){alert(o.error||"Nepoda\u0159ilo se potvrdit odesl\xE1n\xED zpr\xE1vy. Vypln\u011Bn\xFD text z\u016Fst\xE1v\xE1 ve formul\xE1\u0159i.");return}alert(o.message||"Zpr\xE1va byla odesl\xE1na!"),e.reset()}catch(n){console.error("Contact Form Error:",n),alert("Nepoda\u0159ilo se potvrdit odesl\xE1n\xED zpr\xE1vy. Vypln\u011Bn\xFD text z\u016Fst\xE1v\xE1 ve formul\xE1\u0159i; zkuste to pros\xEDm pozd\u011Bji.")}finally{t.textContent=i,t.disabled=!1}})});})();
